const S={...DEFAULT,exterior:'#d7d6c8',exteriorId:DATA.swatches['exterior-standard'][6].id,interiorName:'Branco natural',floorId:DATA.swatches['floor-spc'][1].id,kitchenRef:'kitchen-01',bathroomRef:'bathroom-01',bathroomUV:null,config:'materials',surface:'exterior',exteriorFamily:'exterior-standard'};
const firstExterior=DATA.swatches['exterior-standard'][6], firstFloor=DATA.swatches['floor-spc'][1];
S.exterior=firstExterior.previewHexApprox;S.wallMap=asset(firstExterior.textureAsset);S.floorMap=asset(firstFloor.textureAsset);S.floor=firstFloor.previewHexApprox;
const colourNames=[['Branco natural','#f1eee6'],['Areia','#d9cdbb'],['Cinza pérola','#c9ccc6'],['Verde oliva','#839079'],['Terracota','#ba8970'],['Carvão','#56615a']];
const money=n=>new Intl.NumberFormat('pt-PT',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
let scene,camera,renderer,controls,house,animation=false,previousTime=0,animationStart=0,toastTimer,frameId,paused=false;
const viewport=$('#viewport');
try{
 renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(window.devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.45;viewport.appendChild(renderer.domElement);
 renderer.domElement.setAttribute('aria-hidden','true');
 scene=new THREE.Scene();scene.fog=new THREE.Fog('#e6ecdf',36,80);
 camera=new THREE.PerspectiveCamera(34,1,.1,160);camera.position.set(15.5,11.5,18.5);
 controls=new OrbitControls(camera,renderer.domElement);controls.target.set(0,.65,.25);controls.enableDamping=true;controls.dampingFactor=.075;controls.minDistance=7;controls.maxDistance=38;controls.maxPolarAngle=Math.PI*.485;controls.enablePan=true;
 scene.add(new THREE.HemisphereLight('#fffff2','#afbfa5',2.9));
 const sun=new THREE.DirectionalLight('#fff4da',4.1);sun.position.set(-8,18,12);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-15;sun.shadow.camera.right=15;sun.shadow.camera.top=17;sun.shadow.camera.bottom=-15;sun.shadow.normalBias=.025;sun.shadow.bias=-.0002;scene.add(sun);
 const fill=new THREE.DirectionalLight('#edf5ff',1.8);fill.position.set(10,8,-6);scene.add(fill);
 const ground=new THREE.Mesh(new THREE.PlaneGeometry(200,200),new THREE.MeshStandardMaterial({color:'#e1e8d8',roughness:1}));ground.rotation.x=-Math.PI/2;ground.position.y=-.25;ground.receiveShadow=true;scene.add(ground);
 const plinth=new THREE.Mesh(new THREE.BoxGeometry(7.25,.07,12.8),new THREE.MeshStandardMaterial({color:'#cdd7c4',roughness:1}));plinth.position.y=-.21;plinth.receiveShadow=true;scene.add(plinth);
 const resize=()=>{const {width,height}=viewport.getBoundingClientRect();if(width<1||height<1)return;renderer.setSize(width,height);camera.aspect=width/height;camera.zoom=Math.min(1,Math.max(.5,camera.aspect/1.1));camera.updateProjectionMatrix();};new ResizeObserver(resize).observe(viewport);resize();
 rebuild();$('#loading').hidden=true;
 function tick(t){frameId=requestAnimationFrame(tick);if(paused)return;controls.update();if(animation){const p=Math.min((t-animationStart)/11000,1);setExpansion(p);if(p>=1)stopAnimation();}renderer.render(scene,camera);previousTime=t;}
 frameId=requestAnimationFrame(tick);
 renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();stopAnimation();showToast('O modelo 3D foi interrompido. Recarregue a página para continuar.');});
}catch(error){console.error(error);$('#loading').innerHTML='<div style="padding:35px;text-align:center;max-width:480px"><strong>O 3D precisa de aceleração gráfica.</strong><p>Experimente outro navegador ou active a aceleração gráfica. Pode continuar a explorar as plantas, fotografias e filmes.</p><button class="primary" data-go="films">Ver filmes →</button></div>';}
function rebuild(){if(!scene)return;if(house){scene.remove(house.root);house.dispose();}house=makeHouse(S);scene.add(house.root);applyReferences();}
function applyReferences(){if(!house)return;const k=DATA.kitchens.find(k=>k.id===S.kitchenRef);if(k&&house.materials.kitchen)house.materials.kitchen.color.set(k.previewHexApprox);}
function showToast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function page(id){$$('.page').forEach(e=>e.classList.toggle('active',e.id===id));$$('.nav').forEach(e=>{const active=e.dataset.page===id;e.classList.toggle('active',active);if(active)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current');});paused=id!=='studio';if(paused)stopAnimation();if(id==='plans')renderPlans();if(id!=='films')$$('video').forEach(v=>v.pause());window.scrollTo({top:0,behavior:'smooth'});}
function setView(view){stopAnimation();S.view=view;S.expansion=view==='expansion'?0:1;rebuild();$$('.view').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const labels={exterior:['Vista exterior','Duas alas. Uma nova forma de habitar.'],interior:['Entre e explore','Cobertura e fachadas retiradas para revelar o espaço.'],structure:['A estrutura','Leitura ilustrativa da armação metálica.'],plumbing:['Água e esgotos','Percursos ilustrativos — sem dimensionamento técnico.'],electrical:['Instalação eléctrica','Percursos ilustrativos — sem dimensionamento técnico.'],expansion:['O espaço a desdobrar-se','Explore a sequência com o cursor ou reproduza.']};$('#scene-title').textContent=labels[view][0];$('#view-description').textContent=labels[view][1];$('#expansion-control').hidden=view!=='expansion';const lg=$('#legend');lg.hidden=!['plumbing','electrical'].includes(view);lg.innerHTML=view==='plumbing'?'<span><i style="background:#259ad3"></i>Água fria</span><span><i style="background:#e1765b"></i>Água quente</span><span><i style="background:#649987"></i>Esgotos</span>':'<span><i style="background:#e6ac34"></i>Circuitos ilustrativos</span>';
 if(camera){if(['interior','plumbing','electrical'].includes(view)){camera.position.set(10,16,15);controls.target.set(0,.1,0);}else{camera.position.set(15.5,11.5,18.5);controls.target.set(0,.65,.25);}controls.update();}
 setExpansion(S.expansion);$('#model-note').textContent=['plumbing','electrical'].includes(view)?'Esquema conceptual. Projecto de execução a definir por técnico habilitado.':'Representação 3D ilustrativa, reconstruída a partir das referências.';
}
function setExpansion(p){S.expansion=p;const e=house?house.updateExpansion(p):expansionState(p);$('#expansion-range').value=Math.round(p*100);$('#expansion-percent').textContent=Math.round(p*100)+'%';$('#expansion-stage').textContent=e.label;}
function stopAnimation(){animation=false;$('#play-expansion').textContent='▶';$('#play-expansion').setAttribute('aria-label','Reproduzir expansão');}
function renderPanel(){const el=$('#config-content');const type=S.config;$$('.config-tab').forEach(b=>{b.classList.toggle('active',b.dataset.config===type);b.setAttribute('aria-selected',b.dataset.config===type?'true':'false');b.tabIndex=b.dataset.config===type?0:-1;});
 if(type==='materials')renderMaterials(el);
 if(type==='layout'){el.innerHTML=`<div class="field"><h3>A sua distribuição <span class="value">7 plantas</span></h3><p class="field-description">Da amplitude de um T0 à privacidade de quatro quartos.</p><div class="choice-list">${DATA.layouts.map(p=>`<button class="choice-card ${p.id===S.layout?'active':''}" data-layout="${p.id}" aria-pressed="${p.id===S.layout}"><strong>${esc(p.label)}</strong><small>${p.bedrooms} quarto${p.bedrooms!==1?'s':''} · 1 casa de banho</small><span class="radio"></span></button>`).join('')}</div></div><div class="field"><h3>Planta original</h3><img class="mini-plan" src="${DATA.layouts.find(p=>p.id===S.layout).image}" alt="Planta original ${S.layout}" data-lightbox="${DATA.layouts.find(p=>p.id===S.layout).image}" data-label="Planta original"><p class="field-description">${esc(DATA.layouts.find(p=>p.id===S.layout).description)}</p><button class="text-link" data-go="plans">Comparar todas as plantas ↗</button></div>`;}
 if(type==='kitchen'){el.innerHTML=`<div class="field"><h3>Desenhe a cozinha</h3><p class="field-description">Propostas visuais: a cozinha não está desenhada nas plantas originais.</p><div class="choice-list">${[['linear','Linear','Bancada compacta, numa linha.'],['l','Em L','Duas frentes de trabalho.'],['island','Com ilha','Bancada e módulo central.']].map(([id,n,d])=>`<button class="choice-card ${S.kitchen===id?'active':''}" data-kitchen="${id}" ${S.layout==='t4-a'&&id!=='linear'?'disabled':''} aria-pressed="${S.kitchen===id}"><span><strong>${n}</strong><small>${d}</small></span><span class="radio"></span></button>`).join('')}</div>${S.layout==='t4-a'?'<p class="field-description">Na planta T4 A, o espaço central admite apenas a proposta linear.</p>':''}</div><div class="field"><h3>Referências do catálogo</h3><p class="field-description">Escolha a inspiração para o mobiliário. O tom é aproximado no 3D; consulte a fotografia para os detalhes.</p><div class="reference-options">${DATA.kitchens.map((k,i)=>`<button class="${S.kitchenRef===k.id?'active':''}" data-kitchen-ref="${k.id}" aria-label="Escolher referência de cozinha ${i+1}" aria-pressed="${S.kitchenRef===k.id}"><img loading="lazy" src="${asset(k.asset)}" alt="${esc(k.label)}"><small>${String(i+1).padStart(2,'0')}</small></button>`).join('')}</div><button class="text-link" style="margin-top:12px" data-ref-preview="kitchen">Ampliar referência seleccionada ↗</button></div>`;}
 if(type==='bathroom'){el.innerHTML=`<div class="field"><h3>Casa de banho</h3><p class="field-description">Duche, sanita e lavatório. Uma casa de banho em todas as plantas.</p><div class="choice-list">${[['standard','Distribuição base','Interpretação da planta fornecida.'],['mirrored','Distribuição espelhada','Alternativa conceptual a validar.']].map(([id,n,d])=>`<button class="choice-card ${S.bathroom===id?'active':''}" data-bathroom="${id}" aria-pressed="${S.bathroom===id}"><span><strong>${n}</strong><small>${d}</small></span><span class="radio"></span></button>`).join('')}</div><h3 style="margin-top:23px">Revestimento UV</h3><p class="field-description">8 amostras originais · catálogo, página 17.</p><div class="swatches large">${DATA.swatches['bathroom-uv'].map(x=>swatch(x,S.bathroomUV,'uv')).join('')}</div></div><div class="field"><h3>Ambientes do catálogo</h3><div class="reference-options">${DATA.bathrooms.map((k,i)=>`<button class="${S.bathroomRef===k.id?'active':''}" data-bathroom-ref="${k.id}" aria-label="Seleccionar ambiente de banho ${i+1}" aria-pressed="${S.bathroomRef===k.id}"><img loading="lazy" src="${asset(k.asset)}" alt="${esc(k.label)}"><small>${String(i+1).padStart(2,'0')}</small></button>`).join('')}</div><button class="text-link" style="margin-top:12px" data-ref-preview="bathroom">Ampliar ambiente seleccionado ↗</button><p class="field-description">Referências visuais, sem correspondência automática a dimensões ou equipamentos.</p></div>`;}
 if(type==='roof'){el.innerHTML=`<div class="field"><h3>Protecção, todo o ano.</h3><p class="field-description">Adicione cobertura e um espaço exterior resguardado.</p><label class="toggle-option"><span><strong>Telhado triangular</strong><small>${money(2830)} · referência do catálogo</small></span><input type="checkbox" id="roof-toggle" ${S.roof?'checked':''}></label><label class="toggle-option"><span><strong>Alpendre com cobertura</strong><small>${money(2050)} · referência do catálogo</small></span><input type="checkbox" id="porch-toggle" ${S.porch?'checked':''}></label><p class="field-description">Valores do catálogo com IVA a 23%. A confirmar para esta configuração; não incluem o preço da casa.</p></div><div class="field"><img class="cover-photo" src="assets/alpendre.jpg" alt="Referência fornecida do modelo com telhado e alpendre" data-lightbox="assets/alpendre.jpg" data-label="Telhado e alpendre — referência"><p class="field-description">Geometria do alpendre e do telhado ilustrativa, inspirada na fotografia fornecida.</p></div>`;}
 $('#choice-count').textContent=`${DATA.layouts.find(p=>p.id===S.layout).label} · ${S.roof?'com telhado':'cobertura plana'}${S.porch?' · com alpendre':''}`;
}
function swatch(x,current,kind){return `<button class="swatch ${x.id===current?'active':''}" data-swatch="${x.id}" data-kind="${kind}" title="${esc(x.label)} · p. ${x.page}" aria-label="${esc(x.label)}" aria-pressed="${x.id===current}"><img src="${asset(x.asset)}" alt=""><small>${esc(x.label)}</small></button>`;}
function renderMaterials(el){let body='';
 if(S.surface==='exterior'){const families=[['exterior-standard','Cores incluídas · 12'],['exterior-finishes','Madeira e lamelas · 12'],['exterior-3d-textures','Texturas 3D · 12'],['exterior-3d-gm','Série GM · 15']];const selected=Object.values(DATA.swatches).flat().find(x=>x.id===S.exteriorId);body=`<h3>Fachada <span class="value">${esc(selected?.label||'Cor livre')}</span></h3><label class="sr-only" for="family-select">Família de acabamentos exteriores</label><select id="family-select">${families.map(([id,n])=>`<option value="${id}" ${S.exteriorFamily===id?'selected':''}>${n}</option>`).join('')}</select><div class="swatches large">${DATA.swatches[S.exteriorFamily].map(x=>swatch(x,S.exteriorId,'exterior')).join('')}</div><p class="field-description">${S.exteriorFamily==='exterior-standard'?'Cores indicadas como incluídas no catálogo.':'Acabamentos opcionais do catálogo. Aplicação e valor a confirmar.'} As amostras mantêm as imagens originais.</p><label class="custom-colour">Cor livre <input type="color" value="${S.exterior}" data-colour="exterior" aria-label="Cor exterior personalizada"></label>`;}
 if(S.surface==='floor'){const selected=DATA.swatches['floor-spc'].find(x=>x.id===S.floorId);body=`<h3>Pavimento SPC <span class="value">${esc(selected?.code||selected?.label||'Cor livre')}</span></h3><p class="field-description">12 acabamentos do catálogo · página 11.</p><div class="swatches large">${DATA.swatches['floor-spc'].map(x=>swatch(x,S.floorId,'floor')).join('')}</div><label class="custom-colour">Cor livre <input type="color" value="${S.floor}" data-colour="floor" aria-label="Cor personalizada do pavimento"></label>`;}
 if(S.surface==='interior'){body=`<h3>Paredes interiores</h3><p class="field-description">Paleta de visualização. As cores interiores não estão codificadas no catálogo.</p><div class="swatches">${colourNames.map(([n,c])=>`<button class="swatch ${S.interior===c?'active':''}" data-interior="${c}" data-name="${n}" title="${n}" aria-label="${n}" aria-pressed="${S.interior===c}"><span style="--color:${c}"></span></button>`).join('')}</div><p class="field-description">${esc(S.interiorName)}</p><label class="custom-colour">Cor livre <input type="color" value="${S.interior}" data-colour="interior" aria-label="Cor personalizada das paredes interiores"></label><p class="field-description">O catálogo também apresenta painel de fibra de bambu. A disponibilidade da cor escolhida deve ser confirmada.</p>`;}
 el.innerHTML=`<div class="field"><h3>Escolha a superfície</h3><div class="segmented" role="group" aria-label="Superfície a personalizar">${[['exterior','Exterior'],['interior','Interior'],['floor','Piso']].map(([id,n])=>`<button class="${S.surface===id?'active':''}" data-surface="${id}" aria-pressed="${S.surface===id}">${n}</button>`).join('')}</div>${body}</div><div class="field"><div style="border-top:1px solid var(--line);padding-top:18px"><h3>Acabamentos à vista</h3><p class="field-description">As alterações são aplicadas ao modelo. Rode a casa ou explore o interior para ver os detalhes.</p><button class="text-link" data-view="${S.surface==='exterior'?'exterior':'interior'}">${S.surface==='exterior'?'Ver fachada':'Explorar interior'} ↗</button></div></div>`;
}
function selectLayout(id){S.layout=id;if(id==='t4-a')S.kitchen='linear';$('#current-layout').textContent=DATA.layouts.find(p=>p.id===id).label;rebuild();renderPanel();renderPlans();}
function renderPlans(){$('#plan-grid').innerHTML=DATA.layouts.map(p=>`<article class="plan-card ${p.id===S.layout?'active':''}"><div class="plan-card-head"><h3>${esc(p.label)}</h3><span>${p.bedrooms} quarto${p.bedrooms!==1?'s':''} / 1 WC</span></div><img class="plan-image" src="${p.image}" alt="Planta ${esc(p.label)} original" data-lightbox="${p.image}" data-label="Planta ${esc(p.label)}" loading="lazy"><p>${esc(p.description)}</p><button class="primary" data-use-layout="${p.id}">Explorar esta planta em 3D <span>↗</span></button></article>`).join('');}
const photos=[['assets/frente-envidracada.jpg','Abertura à luz. Frente envidraçada.','FACHADA'],['assets/exterior-creme.jpg','Linhas simples. Acabamento creme.','EXTERIOR'],['assets/exterior-madeira.jpg','A expressão da madeira.','EXTERIOR'],['assets/fachada-madeira.webp','Duas alas, entrada central.','FACHADA'],['assets/exterior-branco.jpg','A arquitectura em branco.','EXTERIOR'],['assets/alpendre.jpg','Um espaço exterior protegido.','COBERTURA'],['assets/expansao.png','O princípio da expansão.','SEQUÊNCIA'],['assets/estrutura.png','A armação metálica.','ESTRUTURA'],['assets/estruturas.png','Tipologias de estrutura e telhado.','REFERÊNCIA']];
$('#gallery-grid').innerHTML=photos.map(([src,title,tag],i)=>`<figure class="gallery-card"><button data-lightbox="${src}" data-label="${esc(title)}" aria-label="Ampliar ${esc(title)}"><img src="${src}" alt="${esc(title)}" loading="lazy"></button><figcaption>${esc(title)}<span>${tag}</span></figcaption></figure>`).join('');
function lightbox(src,label,caption='Imagem de referência fornecida. Não representa necessariamente a configuração seleccionada.'){$('#lightbox-image').src=src;$('#lightbox-image').alt=label;$('#lightbox-label').textContent=label;$('#lightbox-caption').textContent=caption;$('#lightbox').showModal();}
function summaryRows(){const all=Object.values(DATA.swatches).flat(),ext=all.find(x=>x.id===S.exteriorId),fl=all.find(x=>x.id===S.floorId),uv=all.find(x=>x.id===S.bathroomUV);return [['Modelo','Expandível 72 · 40 pés'],['Planta',DATA.layouts.find(p=>p.id===S.layout).label],['Fachada',ext?.label||'Cor livre '+S.exterior],['Paredes interiores',S.interiorName],['Pavimento',fl?.label||'Cor livre '+S.floor],['Cozinha',({linear:'Linear',l:'Em L',island:'Com ilha'})[S.kitchen]+' · referência '+S.kitchenRef.split('-')[1]],['Casa de banho',S.bathroom==='standard'?'Distribuição base':'Distribuição espelhada'],['Revestimento UV',uv?.label||'Por definir'],['Ambiente de banho','Referência '+S.bathroomRef.split('-')[1]],['Telhado triangular',S.roof?'Seleccionado · '+money(2830):'Sem telhado adicional'],['Alpendre coberto',S.porch?'Seleccionado · '+money(2050):'Sem alpendre']];}
function showSummary(){let thumb='';if(renderer){renderer.render(scene,camera);thumb=`<img class="summary-thumbnail" src="${renderer.domElement.toDataURL('image/png')}" alt="Imagem da configuração actual">`;}
$('#summary-content').innerHTML=thumb+`<dl class="details-list">${summaryRows().map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="summary-note">Selecção para apresentação comercial. Valores de cobertura do catálogo com IVA 23%, sujeitos à confirmação de compatibilidade. O preço total da casa não é calculado. Imagens, redes, cores e propostas de implantação são ilustrativas.</p>`;$('#summary').showModal();}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function snapshot(){if(!renderer)return;renderer.render(scene,camera);renderer.domElement.toBlob(blob=>{if(blob){download(blob,'green-village-72-'+S.layout+'.png','image/png');showToast('Imagem da configuração guardada.');}});}
document.addEventListener('click',event=>{const b=event.target.closest('button,a,img[data-lightbox]');if(!b)return;const d=b.dataset;
 if(d.page||d.go)page(d.page||d.go);
 if(d.config){S.config=d.config;renderPanel();}
 if(d.surface){S.surface=d.surface;renderPanel();setView(d.surface==='exterior'?'exterior':'interior');}
 if(d.view)setView(d.view);
 if(d.layout)selectLayout(d.layout);
 if(d.useLayout){selectLayout(d.useLayout);page('studio');setView('interior');S.config='layout';renderPanel();}
 if(d.swatch){const x=Object.values(DATA.swatches).flat().find(s=>s.id===d.swatch);if(d.kind==='exterior'){S.exteriorId=x.id;S.exterior=x.previewHexApprox;S.wallMap=asset(x.textureAsset);S.texture='plain';}if(d.kind==='floor'){S.floorId=x.id;S.floor=x.previewHexApprox;S.floorMap=asset(x.textureAsset);}if(d.kind==='uv'){S.bathroomUV=x.id;S.bathroomMap=asset(x.textureAsset);}rebuild();renderPanel();}
 if(d.interior){S.interior=d.interior;S.interiorName=d.name;rebuild();renderPanel();}
 if(d.kitchen){S.kitchen=d.kitchen;setView('interior');renderPanel();}
 if(d.kitchenRef){S.kitchenRef=d.kitchenRef;rebuild();renderPanel();}
 if(d.bathroom){S.bathroom=d.bathroom;setView('interior');renderPanel();}
 if(d.bathroomRef){S.bathroomRef=d.bathroomRef;renderPanel();const ref=DATA.bathrooms.find(x=>x.id===S.bathroomRef);lightbox(asset(ref.asset),ref.label,'Ambiente original do catálogo, página '+ref.page+'. Referência visual seleccionada no resumo.');}
 if(d.refPreview){const item=d.refPreview==='kitchen'?DATA.kitchens.find(x=>x.id===S.kitchenRef):DATA.bathrooms.find(x=>x.id===S.bathroomRef);lightbox(asset(item.asset),item.label,'Referência original do catálogo, página '+item.page+'.');}
 if(d.lightbox)lightbox(d.lightbox,d.label||'Planta original','Imagem original fornecida para referência.');
 if(b.hasAttribute('data-close'))b.closest('dialog').close();
});
document.addEventListener('change',event=>{const b=event.target;if(b.id==='family-select'){S.exteriorFamily=b.value;renderPanel();}if(b.id==='roof-toggle'||b.id==='porch-toggle'){S[b.id==='roof-toggle'?'roof':'porch']=b.checked;setView('exterior');renderPanel();}if(b.dataset.colour){S[b.dataset.colour]=b.value;if(b.dataset.colour==='exterior'){S.exteriorId=null;S.wallMap=null;}if(b.dataset.colour==='floor'){S.floorId=null;S.floorMap=null;}if(b.dataset.colour==='interior')S.interiorName='Cor livre '+b.value;rebuild();renderPanel();}});
$('.config-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=$$('.config-tab'),i=tabs.indexOf(document.activeElement);const j=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;S.config=tabs[j].dataset.config;renderPanel();tabs[j].focus();});
$('#expansion-range').addEventListener('input',e=>{stopAnimation();setExpansion(Number(e.target.value)/100);});$('#play-expansion').onclick=()=>{if(animation){stopAnimation();return;}animation=true;animationStart=performance.now()-(S.expansion>=1?0:S.expansion)*11000;$('#play-expansion').textContent='Ⅱ';$('#play-expansion').setAttribute('aria-label','Pausar expansão');};
$('#reset-camera').onclick=()=>{if(!camera)return;camera.position.set(15.5,11.5,18.5);controls.target.set(0,.65,.25);controls.update();};$('#zoom-in').onclick=()=>zoom(.85);$('#zoom-out').onclick=()=>zoom(1.18);function zoom(f){if(!camera)return;const v=camera.position.clone().sub(controls.target);v.setLength(THREE.MathUtils.clamp(v.length()*f,7,38));camera.position.copy(controls.target).add(v);controls.update();}
$('#top-camera').onclick=()=>{if(!camera)return;setView('interior');camera.position.set(.001,24,.002);controls.target.set(0,0,0);controls.update();};$('#snapshot').onclick=snapshot;
viewport.addEventListener('keydown',e=>{if(!camera)return;if(['+','=','-'].includes(e.key)){e.preventDefault();zoom(e.key==='-'?1.15:.87);}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const v=camera.position.clone().sub(controls.target),sp=new THREE.Spherical().setFromVector3(v);sp.theta+=(e.key==='ArrowLeft'?.13:e.key==='ArrowRight'?-.13:0);sp.phi=THREE.MathUtils.clamp(sp.phi+(e.key==='ArrowUp'?-.12:e.key==='ArrowDown'?.12:0),.08,1.48);camera.position.copy(controls.target).add(new THREE.Vector3().setFromSpherical(sp));controls.update();}});
$('#review').onclick=showSummary;$('#summary-open').onclick=showSummary;$('#details-open').onclick=()=>$('#detail-dialog').showModal();$('#print-config').onclick=()=>window.print();$('#save-config').onclick=()=>{const content='GREEN VILLAGE — EXPANDÍVEL 72\nCONFIGURAÇÃO COMERCIAL\n\n'+summaryRows().map(([k,v])=>k+': '+v).join('\n')+'\n\nReferências: catálogo 11/07/2026 e plantas de 40 pés fornecidas.\nModelo e instalações ilustrativos. Confirmar compatibilidade, dimensões, cores e preço total na proposta.\n';download(content,'green-village-72-configuracao.txt','text/plain;charset=utf-8');showToast('Escolhas guardadas.');};
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
